function Macro() {
    const sheet = ActiveSheet;
    // 需要删除的列号（A=1, D=4, E=5, G=7）
    const columnsToDelete = [1, 4, 5, 7];

    // 从右往左删除列（避免索引变化影响）
    columnsToDelete
        .sort((a, b) => b - a) // 降序排列
        .forEach(col => sheet.Columns(col).Delete());
}

