function Macro() {
    const sheet = ActiveSheet;
    const columnE = sheet.Columns("E");
    const usedRange = sheet.UsedRange;
    const dashPatterns = ["—","——", "—", "—-", "-—", "--", "--", "-"];
    
    for (let row = 2; row <= 170; row++) {
        const cell = columnE.Rows(row);
        const value = cell.Value2;
        
        if (value && typeof value === "string") {
            let newValue = value;
            for (const pattern of dashPatterns) {
                newValue = newValue.replace(new RegExp(pattern, "g"), "-");
            }
            if (newValue !== value) {
                cell.Value2 = newValue;
            }
        }
    }
}

